--
-- Name: fn_calculate_player_market_value(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_calculate_player_market_value(p_student_id integer) RETURNS numeric
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_base_price NUMERIC(10, 2);
    v_total_goals INT := 0;
    v_total_assists INT := 0;
    v_yellow_cards INT := 0;
    v_red_cards INT := 0;
    v_match_count INT := 0;
    v_performance_score NUMERIC(10, 2) := 0.00;
    v_new_price NUMERIC(10, 2) := 0.00;
    
    -- Record variable for event iteration
    v_event RECORD;
BEGIN
    -- 1. Validate player existence and fetch current price
    SELECT current_price INTO v_base_price
    FROM Students
    WHERE student_id = p_student_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Player with ID % does not exist.', p_student_id;
    END IF;

    -- If price is uninitialized, assign base value
    IF v_base_price IS NULL OR v_base_price <= 0 THEN
        v_base_price := 10.00;
    END IF;

    -- 2. Count distinct matches played
    SELECT COUNT(DISTINCT match_id) INTO v_match_count
    FROM Match_Lineups
    WHERE student_id = p_student_id;

    -- 3. Iterate over player match events using a cursor loop
    FOR v_event IN
        SELECT event_type
        FROM Match_Events
        WHERE student_id = p_student_id
    LOOP
        CASE v_event.event_type
            WHEN 'Goal' THEN
                v_total_goals := v_total_goals + 1;
            WHEN 'Assist' THEN
                v_total_assists := v_total_assists + 1;
            WHEN 'Yellow Card' THEN
                v_yellow_cards := v_yellow_cards + 1;
            WHEN 'Red Card' THEN
                v_red_cards := v_red_cards + 1;
            ELSE
                NULL;
        END CASE;
    END LOOP;

    -- 4. Calculate performance score
    -- Goals: +5.0, Assists: +3.0, Matches: +1.0, Yellow: -1.5, Red: -4.0
    v_performance_score := (v_total_goals * 5.0) 
                         + (v_total_assists * 3.0) 
                         + (v_match_count * 1.0) 
                         - (v_yellow_cards * 1.5) 
                         - (v_red_cards * 4.0);

    -- Ensure non-negative performance adjustment
    IF v_performance_score < 0 THEN
        v_performance_score := 0;
    END IF;

    -- 5. Calculate new adjusted price
    v_new_price := ROUND(v_base_price * (1.0 + (v_performance_score / 100.0)), 2);

    RAISE NOTICE 'Player ID: %, Matches: %, Goals: %, Assists: %, Current Price: %, Adjusted Price: %',
        p_student_id, v_match_count, v_total_goals, v_total_assists, v_base_price, v_new_price;

    RETURN v_new_price;

EXCEPTION
    WHEN OTHERS THEN
        RAISE NOTICE 'Error calculating market value for Student %: %', p_student_id, SQLERRM;
        RETURN NULL;
END;
$$;


ALTER FUNCTION public.fn_calculate_player_market_value(p_student_id integer) OWNER TO postgres;

--
-- Name: fn_calculate_player_market_value(character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_calculate_player_market_value(p_student_id character varying) RETURNS numeric
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_base_price NUMERIC(10, 2);
    v_total_goals INT := 0;
    v_total_assists INT := 0;
    v_yellow_cards INT := 0;
    v_red_cards INT := 0;
    v_match_count INT := 0;
    v_performance_score NUMERIC(10, 2) := 0.00;
    v_new_price NUMERIC(10, 2) := 0.00;

    -- Record variable for event iteration
    v_event RECORD;
BEGIN
    -- 1. Validate player existence and fetch current price
    SELECT current_price INTO v_base_price
    FROM Students
    WHERE student_id = p_student_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Player with ID % does not exist.', p_student_id;
    END IF;

    -- If price is uninitialized, assign base value
    IF v_base_price IS NULL OR v_base_price <= 0 THEN
        v_base_price := 10.00;
    END IF;

    -- 2. Count distinct matches played (derived from recorded match events)
    SELECT COUNT(DISTINCT match_id) INTO v_match_count
    FROM Match_Events
    WHERE student_id = p_student_id;

    -- 3. Iterate over player match events using a cursor loop
    FOR v_event IN
        SELECT event_type::TEXT AS event_name
        FROM Match_Events
        WHERE student_id = p_student_id
    LOOP
        CASE v_event.event_name
            WHEN 'Goal' THEN
                v_total_goals := v_total_goals + 1;
            WHEN 'Assist' THEN
                v_total_assists := v_total_assists + 1;
            WHEN 'Yellow Card' THEN
                v_yellow_cards := v_yellow_cards + 1;
            WHEN 'Red Card' THEN
                v_red_cards := v_red_cards + 1;
            ELSE
                NULL;
        END CASE;
    END LOOP;

    -- 4. Calculate performance score
    -- Goals: +5.0, Assists: +3.0, Matches: +1.0, Yellow: -1.5, Red: -4.0
    v_performance_score := (v_total_goals * 5.0)
                         + (v_total_assists * 3.0)
                         + (v_match_count * 1.0)
                         - (v_yellow_cards * 1.5)
                         - (v_red_cards * 4.0);

    -- Ensure non-negative performance adjustment
    IF v_performance_score < 0 THEN
        v_performance_score := 0;
    END IF;

    -- 5. Calculate new adjusted price
    v_new_price := ROUND(v_base_price * (1.0 + (v_performance_score / 100.0)), 2);

    RAISE NOTICE 'Player ID: %, Matches: %, Goals: %, Assists: %, Current Price: %, Adjusted Price: %',
        p_student_id, v_match_count, v_total_goals, v_total_assists, v_base_price, v_new_price;

    RETURN v_new_price;

EXCEPTION
    WHEN OTHERS THEN
        RAISE NOTICE 'Error calculating market value for Student %: %', p_student_id, SQLERRM;
        RETURN NULL;
END;
$$;


ALTER FUNCTION public.fn_calculate_player_market_value(p_student_id character varying) OWNER TO postgres;

--
-- Name: fn_evaluate_squad_compliance(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_evaluate_squad_compliance(p_user_id integer) RETURNS public.squad_compliance_result
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_result             squad_compliance_result;
    v_budget             NUMERIC(12, 2);
    v_squad_row          RECORD;
    v_total_players      INT := 0;
    v_starting           INT := 0;
    v_bench              INT := 0;
    v_squad_value        NUMERIC(12, 2) := 0.00;

    c_max_squad_size     CONSTANT INT := 15;
    c_required_starters  CONSTANT INT := 11;
BEGIN
    -- 1. Validate that the fantasy user exists and fetch their budget
    SELECT current_budget INTO v_budget
    FROM USERS
    WHERE user_id = p_user_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'User with ID % does not exist.', p_user_id;
    END IF;

    -- 2. Walk the user's squad with a cursor loop, classifying each player
    --    by lineup status and accumulating total market value
    FOR v_squad_row IN
        SELECT us.lineup_status, s.current_price
        FROM USER_SQUADS us
        JOIN Students s ON s.student_id = us.player_id
        WHERE us.user_id = p_user_id
    LOOP
        v_total_players := v_total_players + 1;
        v_squad_value := v_squad_value + COALESCE(v_squad_row.current_price, 0);

        CASE v_squad_row.lineup_status
            WHEN 'Starting XI' THEN
                v_starting := v_starting + 1;
            WHEN 'Bench' THEN
                v_bench := v_bench + 1;
            ELSE
                NULL;
        END CASE;
    END LOOP;

    -- 3. Populate the result and apply league compliance rules
    v_result.user_id := p_user_id;
    v_result.total_players := v_total_players;
    v_result.starting_count := v_starting;
    v_result.bench_count := v_bench;
    v_result.squad_value := v_squad_value;
    v_result.current_budget := v_budget;

    IF v_total_players = 0 THEN
        v_result.is_compliant := FALSE;
        v_result.status_message := 'No players registered in squad.';
    ELSIF v_total_players > c_max_squad_size THEN
        v_result.is_compliant := FALSE;
        v_result.status_message := FORMAT('Squad exceeds maximum size of %s players.', c_max_squad_size);
    ELSIF v_starting <> c_required_starters THEN
        v_result.is_compliant := FALSE;
        v_result.status_message := FORMAT(
            'Starting lineup must contain exactly %s players (found %s).',
            c_required_starters, v_starting
        );
    ELSE
        v_result.is_compliant := TRUE;
        v_result.status_message := 'Squad meets all roster requirements.';
    END IF;

    RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        RAISE NOTICE 'Error evaluating squad compliance for User %: %', p_user_id, SQLERRM;
        RETURN NULL;
END;
$$;


ALTER FUNCTION public.fn_evaluate_squad_compliance(p_user_id integer) OWNER TO postgres;

--
-- Name: sp_process_player_transfer(integer, character varying, character varying); Type: PROCEDURE; Schema: public; Owner: postgres
--

CREATE PROCEDURE public.sp_process_player_transfer(IN p_user_id integer, IN p_player_id character varying, IN p_action_type character varying, OUT p_success boolean, OUT p_message character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_budget          NUMERIC(12, 2);
    v_price           NUMERIC(10, 2);
    v_squad_count     INT;
    v_squad_record_id INT;
    v_next_squad_id   INT;
    v_next_tx_id      INT;
    v_sell_price      NUMERIC(10, 2);

    c_max_squad_size  CONSTANT INT := 15;
    c_resale_fee_rate CONSTANT NUMERIC(4, 2) := 0.05;
BEGIN
    p_success := FALSE;
    p_message := NULL;

    -- 1. Validate the requested action
    IF p_action_type NOT IN ('BUY', 'SELL') THEN
        RAISE EXCEPTION 'Invalid action type "%": must be BUY or SELL.', p_action_type;
    END IF;

    -- 2. Validate the user exists and lock their budget row for this transfer
    SELECT current_budget INTO v_budget
    FROM USERS
    WHERE user_id = p_user_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'User with ID % does not exist.', p_user_id;
    END IF;

    -- 3. Validate the player exists and fetch the current market price
    SELECT current_price INTO v_price
    FROM Students
    WHERE student_id = p_player_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Player with ID % does not exist.', p_player_id;
    END IF;

    IF p_action_type = 'BUY' THEN
        -- 4a. A player cannot be bought twice by the same user
        SELECT COUNT(*) INTO v_squad_count
        FROM USER_SQUADS
        WHERE user_id = p_user_id AND player_id = p_player_id;

        IF v_squad_count > 0 THEN
            RAISE EXCEPTION 'Player % is already in the squad of User %.', p_player_id, p_user_id;
        END IF;

        -- 4b. Enforce the maximum roster size
        SELECT COUNT(*) INTO v_squad_count
        FROM USER_SQUADS
        WHERE user_id = p_user_id;

        IF v_squad_count >= c_max_squad_size THEN
            RAISE EXCEPTION 'User % squad is full (max % players).', p_user_id, c_max_squad_size;
        END IF;

        -- 4c. Enforce sufficient budget
        IF v_budget < v_price THEN
            RAISE EXCEPTION 'Insufficient budget for User % (budget %, price %).',
                p_user_id, v_budget, v_price;
        END IF;

        -- 4d. Debit the budget
        UPDATE USERS
        SET current_budget = current_budget - v_price
        WHERE user_id = p_user_id;

        -- 4e. Add the player to the squad
        SELECT COALESCE(MAX(squad_record_id), 0) + 1 INTO v_next_squad_id FROM USER_SQUADS;

        VALUES (v_next_squad_id, 'Bench', p_user_id, p_player_id);

        -- 4f. Record the transaction
        SELECT COALESCE(MAX(transaction_id), 0) + 1 INTO v_next_tx_id FROM TRANSACTIONS;

        VALUES (v_next_tx_id, CURRENT_TIMESTAMP, 'BUY', v_price, p_user_id, p_player_id);

        p_success := TRUE;
        p_message := FORMAT('User %s bought player %s for %s.', p_user_id, p_player_id, v_price);

    ELSE -- SELL
        -- 5a. The player must currently be owned by the user
        SELECT squad_record_id INTO v_squad_record_id
        FROM USER_SQUADS
        WHERE user_id = p_user_id AND player_id = p_player_id;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'Player % is not owned by User %.', p_player_id, p_user_id;
        END IF;

        -- 5b. Apply the resale fee
        v_sell_price := ROUND(v_price * (1 - c_resale_fee_rate), 2);

        -- 5c. Remove the player from the squad
        DELETE FROM USER_SQUADS WHERE squad_record_id = v_squad_record_id;

        -- 5d. Credit the budget
        UPDATE USERS
        SET current_budget = current_budget + v_sell_price
        WHERE user_id = p_user_id;

        -- 5e. Record the transaction
        SELECT COALESCE(MAX(transaction_id), 0) + 1 INTO v_next_tx_id FROM TRANSACTIONS;

        VALUES (v_next_tx_id, CURRENT_TIMESTAMP, 'SELL', v_sell_price, p_user_id, p_player_id);

        p_success := TRUE;
        p_message := FORMAT('User %s sold player %s for %s (after %s%% fee).',
            p_user_id, p_player_id, v_sell_price, c_resale_fee_rate * 100);
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        p_success := FALSE;
        p_message := SQLERRM;
        RAISE NOTICE 'Transfer failed for User % / Player % (%): %',
            p_user_id, p_player_id, p_action_type, SQLERRM;
END;
$$;


ALTER PROCEDURE public.sp_process_player_transfer(IN p_user_id integer, IN p_player_id character varying, IN p_action_type character varying, OUT p_success boolean, OUT p_message character varying) OWNER TO postgres;

--
-- Name: sp_settle_round(integer); Type: PROCEDURE; Schema: public; Owner: postgres
--

CREATE PROCEDURE public.sp_settle_round(IN p_round_id integer, OUT p_players_processed integer, OUT p_errors_encountered integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_round_number    INT;
    v_status          VARCHAR(50);
    v_player          RECORD;
    v_new_price       NUMERIC(10, 2);
    v_next_history_id INT;
    v_activated_next  INT := 0;
BEGIN
    p_players_processed := 0;
    p_errors_encountered := 0;

    -- 1. Validate the round exists and is ready to be settled
    SELECT round_number, status INTO v_round_number, v_status
    FROM ROUNDS
    WHERE round_id = p_round_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Round with ID % does not exist.', p_round_id;
    END IF;

    IF v_status <> 'Active' THEN
        RAISE EXCEPTION 'Round % cannot be settled: current status is "%" (must be "Active").',
            p_round_id, v_status;
    END IF;

    -- 2. Prime the PRICE_HISTORY sequence value once, then increment locally
    SELECT COALESCE(MAX(history_id), 0) INTO v_next_history_id FROM PRICE_HISTORY;

    -- 3. Revalue every distinct player currently held in a fantasy squad
    FOR v_player IN
        SELECT DISTINCT player_id FROM USER_SQUADS
    LOOP
        BEGIN
            v_new_price := fn_calculate_player_market_value(v_player.player_id);

            IF v_new_price IS NULL THEN
                RAISE EXCEPTION 'Valuation returned NULL for player %.', v_player.player_id;
            END IF;

            UPDATE Students
            SET current_price = v_new_price
            WHERE student_id = v_player.player_id;

            v_next_history_id := v_next_history_id + 1;

            VALUES (v_next_history_id, v_new_price, v_player.player_id, p_round_id);

            p_players_processed := p_players_processed + 1;

        EXCEPTION
            WHEN OTHERS THEN
                -- Error recovery: skip this player, keep settling the rest
                p_errors_encountered := p_errors_encountered + 1;
                RAISE NOTICE 'Skipping player % during settlement of round %: %',
                    v_player.player_id, p_round_id, SQLERRM;
        END;
    END LOOP;

    -- 4. Close out the round
    UPDATE ROUNDS
    SET status = 'Completed'
    WHERE round_id = p_round_id;

    -- 5. Conditionally activate the next round, if one is waiting
    UPDATE ROUNDS
    SET status = 'Active'
    WHERE round_number = v_round_number + 1
      AND status = 'Upcoming';

    GET DIAGNOSTICS v_activated_next = ROW_COUNT;

    RAISE NOTICE 'Round % settled: % players processed, % errors, next round activated: %',
        p_round_id, p_players_processed, p_errors_encountered, (v_activated_next > 0);
END;
$$;


ALTER PROCEDURE public.sp_settle_round(IN p_round_id integer, OUT p_players_processed integer, OUT p_errors_encountered integer) OWNER TO postgres;

--
-- Name: trg_fn_students_recalculate_price(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trg_fn_students_recalculate_price() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        NEW.current_price := ROUND(30.00 + (NEW.technical_rating * 0.70) + (NEW.mental_rating * 0.30), 2);

    ELSIF TG_OP = 'UPDATE' THEN
        IF NEW.technical_rating IS DISTINCT FROM OLD.technical_rating
           OR NEW.mental_rating IS DISTINCT FROM OLD.mental_rating THEN

            NEW.current_price := ROUND(30.00 + (NEW.technical_rating * 0.70) + (NEW.mental_rating * 0.30), 2);
        END IF;
    END IF;

    RETURN NEW;

EXCEPTION
    WHEN OTHERS THEN
        RAISE WARNING 'Failed to auto-calculate price for student %: %', NEW.student_id, SQLERRM;
        RETURN NEW;
END;
$$;


ALTER FUNCTION public.trg_fn_students_recalculate_price() OWNER TO postgres;

--
-- Name: trg_fn_users_budget_audit(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trg_fn_users_budget_audit() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- State validation: budget can never go negative
    IF NEW.current_budget < 0 THEN
        RAISE EXCEPTION 'Update rejected: User % budget cannot go negative (attempted %).',
            OLD.user_id, NEW.current_budget;
    END IF;

    -- Auditing: only log meaningful budget changes
    IF NEW.current_budget IS DISTINCT FROM OLD.current_budget THEN
        VALUES (OLD.user_id, OLD.current_budget, NEW.current_budget, NEW.current_budget - OLD.current_budget);
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION public.trg_fn_users_budget_audit() OWNER TO postgres;

