--
-- Name: v_fantasy_user_portfolio_summary; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_fantasy_user_portfolio_summary AS
 SELECT u.user_id,
    u.user_name,
    u.current_budget,
    count(DISTINCT us.squad_record_id) AS total_squad_players,
    count(DISTINCT
        CASE
            WHEN ((us.lineup_status)::text = 'Starting XI'::text) THEN us.squad_record_id
            ELSE NULL::integer
        END) AS starting_players,
    COALESCE(sum(s.current_price), (0)::numeric) AS squad_market_value,
    count(DISTINCT s.school_id) AS distinct_schools_represented,
    count(DISTINCT tx.transaction_id) AS total_market_transactions
   FROM (((public.users u
     LEFT JOIN public.user_squads us ON ((u.user_id = us.user_id)))
     LEFT JOIN public.students s ON (((us.player_id)::text = (s.student_id)::text)))
     LEFT JOIN public.transactions tx ON ((u.user_id = tx.user_id)))
  GROUP BY u.user_id, u.user_name, u.current_budget;


ALTER VIEW public.v_fantasy_user_portfolio_summary OWNER TO postgres;

--
-- Name: v_school_player_market_performance; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_school_player_market_performance AS
 SELECT s.student_id,
    concat(s.first_name, ' ', s.last_name) AS full_name,
    sc.school_name,
    t.team_name,
    s.preferred_position,
    s.technical_rating,
    s.mental_rating,
    s.current_price,
    COALESCE(sum(
        CASE
            WHEN (me.event_type = 'Goal'::public.event_type_enum) THEN 1
            ELSE 0
        END), (0)::bigint) AS total_goals,
    COALESCE(sum(
        CASE
            WHEN (me.event_type = 'Yellow Card'::public.event_type_enum) THEN 1
            ELSE 0
        END), (0)::bigint) AS yellow_cards,
    COALESCE(sum(
        CASE
            WHEN (me.event_type = 'Red Card'::public.event_type_enum) THEN 1
            ELSE 0
        END), (0)::bigint) AS red_cards,
    count(DISTINCT us.user_id) AS fantasy_team_selections
   FROM (((((public.students s
     JOIN public.schools sc ON ((s.school_id = sc.school_id)))
     JOIN public.team_players tp ON (((s.student_id)::text = (tp.student_id)::text)))
     JOIN public.teams t ON ((tp.team_id = t.team_id)))
     LEFT JOIN public.match_events me ON (((s.student_id)::text = (me.student_id)::text)))
     LEFT JOIN public.user_squads us ON (((s.student_id)::text = (us.player_id)::text)))
  GROUP BY s.student_id, s.first_name, s.last_name, sc.school_name, t.team_name, s.preferred_position, s.technical_rating, s.mental_rating, s.current_price;


ALTER VIEW public.v_school_player_market_performance OWNER TO postgres;

